import numpy as np
from scipy.optimize import least_squares
ones=np.ones_like(t)
hs={'1':ones,'x':x,'v':v,'sqrt v':np.sqrt(v),'v^1.5':v**1.5,'xv':x*v,'x/(1+x)':x/(1+x),'sqrt x':np.sqrt(x),'x^2':x**2,'v^2':v**2}
def run(kind,h):
    best=None
    for w0 in [0.2,0.5,1,2,3,5]:
        def res(p):
            if kind=='cos': g=np.cos(p[0]*t)
            elif kind=='sin': g=np.sin(p[0]*t)
            elif kind=='exp': g=np.exp(-p[0]*t)
            elif kind=='t2': g=np.exp(-p[0]*t**2)
            M=np.column_stack([v**1.5, x/(1+p[1]*x)*np.sqrt(v), ones, t, t**2, g*h])
            coef,*_=np.linalg.lstsq(M,dv_dt,rcond=None)
            return M@coef-dv_dt
        try:
            rr=least_squares(res,[w0,0.5])
            if best is None or rr.cost<best.cost: best=rr
        except Exception: pass
    return np.sum(best.fun**2)/np.sum((dv_dt-dv_dt.mean())**2), best.x
out=[]
for k in ['cos','sin','exp','t2']:
    for hn,h in hs.items():
        e,p=run(k,h); out.append((e,k,hn,p))
out.sort(key=lambda z:z[0])
for o in out[:10]: print(o)

